<script lang="ts">
 import {enhance} from '$app/forms';
 let {data,enhanced,busy}:{data:any,enhanced:any,busy:boolean}=$props();
</script>
<section class="p-card"><p class="p-kicker">FIELD ALERTS</p><h2>Know when to take a closer look.</h2><p>Alerts compare two usable satellite observations. They are inspection prompts, not confirmed crop diagnoses.</p>
 {#if data.section==='account'}<form method="POST" action="?/alertPreferences" use:enhance={enhanced} class="p-form"><label class="p-field">In-app stress alerts<select aria-label="In-app stress alerts" name="enabled" value={data.alertPreference?.enabled?'true':'false'}><option value="false">Off</option><option value="true">On</option></select></label><label class="p-field">NDVI decrease threshold<input type="number" name="threshold" min="0.01" max="1" step="0.01" value={data.alertPreference?.ndvi_drop||.15} required/></label><button class="p-button" disabled={busy}>Save alert preference</button></form><p class="p-caption">Delivery is inside Talazo. SMS and email stress delivery are not enabled.</p>{/if}
 {#each data.alerts||[] as alert}{@const m=data.tables.talazo_monitoring.find((v:any)=>v.id===alert.monitoring_id)}{@const zone=data.tables.talazo_zones.find((v:any)=>v.id===m?.zone_id)}<article><h3>{zone?.name||'Field'} · vegetation change</h3><p>{alert.data.message}</p><p class="p-caption">{alert.data.previous?.toFixed(2)} → {alert.data.current?.toFixed(2)} · Observation {alert.observed_on}</p><a href={'/portal/health?field='+zone?.id}>Review field</a>{#if !alert.acknowledged_at}<form method="POST" action="?/acknowledgeAlert" use:enhance={enhanced}><input type="hidden" name="alert" value={alert.id}/><button class="p-button subtle" disabled={busy}>Mark reviewed</button></form>{:else}<p class="p-caption">Reviewed</p>{/if}</article>{:else}<p>No stress alerts recorded. You can enable in-app alerts in Account & support.</p>{/each}
</section>
